<?php if(session('error') || session('errors')): ?><div class="mt-5 rounded-xl bg-[#f8e6df] p-3 text-sm font-semibold text-[#a4573a]"><?php $errors=session('errors') ?: [session('error')]; foreach((array)$errors as $error): ?><p><?= esc($error) ?></p><?php endforeach ?></div><?php endif ?><?php if(session('message')): ?><div class="mt-5 rounded-xl bg-[#dff4e9] p-3 text-sm font-semibold text-[#23785f]"><?= esc(session('message')) ?></div><?php endif ?>
